-- DaNest 10B.4.1D | Read-only acceptance after approved orphan draft cleanup. Run entire file.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';
WITH f AS (SELECT * FROM public.properties WHERE seed_key LIKE 'CAP-10B2-20261127-%'),
i AS (SELECT q.*,p.owner_id FROM public.inquiries q LEFT JOIN public.properties p ON p.id=q.listing_id),
fi AS (SELECT * FROM i WHERE seed_key LIKE 'CAP-10B3-20261127-I-%'),
v AS (SELECT * FROM i WHERE status='viewing_scheduled' AND scheduled_at IS NOT NULL),
checks(name,actual,expected,level) AS (VALUES
('01_public_tables',(SELECT count(*) FROM pg_tables WHERE schemaname='public'),27,'FAIL'),
('02_tables_without_rls',(SELECT count(*) FROM pg_tables WHERE schemaname='public' AND NOT rowsecurity),0,'FAIL'),
('03_unvalidated_public_fk',(SELECT count(*) FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='public' AND c.contype='f' AND NOT c.convalidated),0,'WARN'),
('04_profiles',(SELECT count(*) FROM public.profiles),7,'FAIL'),
('05_active_admin',(SELECT count(*) FROM public.profiles WHERE role='admin' AND account_status='active'),1,'FAIL'),
('06_active_landlords',(SELECT count(*) FROM public.profiles WHERE role='landlord' AND account_status='active'),2,'FAIL'),
('07_active_renters',(SELECT count(*) FROM public.profiles WHERE role='tenant' AND account_status='active'),4,'FAIL'),
('08_profiles_missing_auth',(SELECT count(*) FROM public.profiles p WHERE NOT EXISTS(SELECT 1 FROM auth.users a WHERE a.id=p.id)),0,'FAIL'),
('09_auth_missing_profile',(SELECT count(*) FROM auth.users a WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id)),0,'WARN'),
('10_unconfirmed_email_state',(SELECT count(*) FROM public.profiles p JOIN auth.users a ON a.id=p.id WHERE a.email_confirmed_at IS NULL),0,'WARN'),
('11_listings',(SELECT count(*) FROM public.properties),40,'FAIL'),
('12_published',(SELECT count(*) FROM public.properties WHERE status='published'),36,'FAIL'),
('13_not_published',(SELECT count(*) FROM public.properties WHERE status<>'published'),4,'FAIL'),
('14_legacy_demo_published',(SELECT count(*) FROM public.properties WHERE is_demo AND status='published'),30,'FAIL'),
('15_cap_listings',(SELECT count(*) FROM f),8,'FAIL'),
('16_cap_owner_count',(SELECT count(DISTINCT owner_id) FROM f),2,'FAIL'),
('17_cap_ready',(SELECT count(*) FROM f WHERE status='published' AND availability='available' AND owner_id IS NOT NULL),5,'FAIL'),
('18_cap_private',(SELECT count(*) FROM f WHERE status<>'published'),3,'FAIL'),
('19_cap_bad_owner',(SELECT count(*) FROM f x LEFT JOIN public.profiles p ON p.id=x.owner_id WHERE p.role IS DISTINCT FROM 'landlord' OR p.account_status IS DISTINCT FROM 'active'),0,'FAIL'),
('20_cap_unexpected_badge',(SELECT count(*) FROM f WHERE verification_level IS DISTINCT FROM 'unverified'),0,'FAIL'),
('21_cap_missing_image_cost_area',(SELECT count(*) FROM f x WHERE x.neighborhood_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.listing_image a WHERE a.listing_id=x.id) OR NOT EXISTS(SELECT 1 FROM public.listing_cost c WHERE c.listing_id=x.id)),0,'FAIL'),
('22_legacy_demo_ownerless',(SELECT count(*) FROM public.properties WHERE is_demo AND owner_id IS NULL),30,'WARN'),
('23_non_demo_ownerless',(SELECT count(*) FROM public.properties WHERE NOT is_demo AND owner_id IS NULL),0,'WARN'),
('24_all_missing_image',(SELECT count(*) FROM public.properties p WHERE NOT EXISTS(SELECT 1 FROM public.listing_image a WHERE a.listing_id=p.id)),0,'WARN'),
('25_all_missing_cost',(SELECT count(*) FROM public.properties p WHERE NOT EXISTS(SELECT 1 FROM public.listing_cost c WHERE c.listing_id=p.id)),0,'WARN'),
('26_all_missing_area',(SELECT count(*) FROM public.properties WHERE neighborhood_id IS NULL),0,'WARN'),
('27_inquiries',(SELECT count(*) FROM i),20,'FAIL'),
('28_cap_inquiries',(SELECT count(*) FROM fi),19,'FAIL'),
('29_inquiry_bad_participants',(SELECT count(*) FROM i q LEFT JOIN public.profiles t ON t.id=q.tenant_id LEFT JOIN public.profiles o ON o.id=q.owner_id WHERE t.role IS DISTINCT FROM 'tenant' OR o.role IS DISTINCT FROM 'landlord' OR q.tenant_id=q.owner_id),0,'FAIL'),
('30_cap_inquiry_wrong_listing',(SELECT count(*) FROM fi q WHERE NOT EXISTS(SELECT 1 FROM f x WHERE x.id=q.listing_id)),0,'FAIL'),
('31_history_missing_current_state',(SELECT count(*) FROM i q WHERE NOT EXISTS(SELECT 1 FROM public.inquiry_status_history h WHERE h.inquiry_id=q.id AND h.to_status=q.status AND NOT EXISTS(SELECT 1 FROM public.inquiry_status_history h2 WHERE h2.inquiry_id=q.id AND h2.changed_at>h.changed_at))),0,'FAIL'),
('32_viewings_confirmed',(SELECT count(*) FROM v),8,'FAIL'),
('33_viewing_missing_schedule',(SELECT count(*) FROM i WHERE status='viewing_scheduled' AND scheduled_at IS NULL),0,'FAIL'),
('34_viewing_conflict_under_60min',(SELECT count(*) FROM v a JOIN v b ON a.id<b.id AND (a.owner_id=b.owner_id OR a.tenant_id=b.tenant_id) AND b.scheduled_at>a.scheduled_at-interval '1 hour' AND b.scheduled_at<a.scheduled_at+interval '1 hour'),0,'FAIL'),
('35_messages',(SELECT count(*) FROM public.inquiry_messages),64,'FAIL'),
('36_message_bad_sender',(SELECT count(*) FROM public.inquiry_messages m LEFT JOIN i q ON q.id=m.inquiry_id WHERE q.id IS NULL OR (m.sender_id IS DISTINCT FROM q.tenant_id AND m.sender_id IS DISTINCT FROM q.owner_id)),0,'FAIL'),
('37_cap_inquiry_without_message',(SELECT count(*) FROM fi q WHERE NOT EXISTS(SELECT 1 FROM public.inquiry_messages m WHERE m.inquiry_id=q.id)),0,'FAIL'),
('38_reports',(SELECT count(*) FROM public.reports),5,'FAIL'),
('39_report_bad_links',(SELECT count(*) FROM public.reports r LEFT JOIN public.properties p ON p.id=r.listing_id LEFT JOIN public.profiles u ON u.id=r.reporter_id WHERE p.id IS NULL OR u.id IS NULL),0,'FAIL'),
('40_promotions',(SELECT count(*) FROM public.listing_promotion),4,'FAIL'),
('41_promotion_wrong_owner_or_admin',(SELECT count(*) FROM public.listing_promotion c LEFT JOIN public.properties p ON p.id=c.listing_id LEFT JOIN public.profiles a ON a.id=c.activated_by WHERE p.id IS NULL OR c.requested_by IS DISTINCT FROM p.owner_id OR (c.activated_by IS NOT NULL AND a.role IS DISTINCT FROM 'admin') OR (c.active AND (c.activated_by IS NULL OR c.start_date IS NULL OR c.end_date IS NULL OR c.end_date<c.start_date))),0,'FAIL'),
('42_saved_apartments',(SELECT count(*) FROM public.saved_apartments),20,'FAIL'),
('43_saved_bad_links',(SELECT count(*) FROM public.saved_apartments s LEFT JOIN public.profiles u ON u.id=s.user_id LEFT JOIN public.properties p ON p.id=s.listing_id WHERE u.role IS DISTINCT FROM 'tenant' OR p.id IS NULL),0,'FAIL'),
('44_notification_bad_participant',(SELECT count(*) FROM public.notifications n LEFT JOIN i q ON q.id=n.inquiry_id WHERE n.inquiry_id IS NOT NULL AND (q.id IS NULL OR (n.recipient_id IS DISTINCT FROM q.tenant_id AND n.recipient_id IS DISTINCT FROM q.owner_id))),0,'WARN'),
('45_cap_analytics',(SELECT count(*) FROM public.listing_analytics_09d1 a JOIN fi q ON a.listing_id=q.listing_id AND a.dedup_key=md5(q.id::text) WHERE a.kind='inquiry'),19,'FAIL'),
('46_batch_audit_marker',(SELECT count(*) FROM public.audit_log WHERE seed_key='CAP-10B3-20261127' AND actor_type='system' AND actor_id IS NULL AND action='cap-test-workflow-seeded'),1,'FAIL'),
('47_email_opt_in',(SELECT count(*) FROM public.profiles WHERE email_notices_10a14),0,'WARN'),
('48_private_buckets',(SELECT count(*) FROM storage.buckets WHERE id IN ('listing-images','verification-evidence') AND NOT public),2,'FAIL'),
('49_evidence_metadata_missing_object',(SELECT count(*) FROM public.evidence_document d WHERE NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='verification-evidence' AND o.name=d.storage_ref)),0,'FAIL'),
('50_evidence_test_witness',(SELECT count(*) FROM public.evidence_document d JOIN public.properties p ON p.id=d.listing_id WHERE p.seed_key='CAP-10B2-20261127-08' AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='verification-evidence' AND o.name=d.storage_ref)),1,'SKIP'),
('51_inquiry_new',(SELECT count(*) FROM i WHERE status='new'),5,'WARN'),
('52_inquiry_replied',(SELECT count(*) FROM i WHERE status='replied'),4,'WARN'),
('53_inquiry_rented',(SELECT count(*) FROM i WHERE status='rented'),2,'WARN'),
('54_inquiry_not_proceeding',(SELECT count(*) FROM i WHERE status='not_proceeding'),1,'WARN')
), results AS (SELECT name AS check_name, actual,expected,CASE WHEN level='SKIP' THEN CASE WHEN actual>=expected THEN 'PASS' ELSE 'SKIP' END WHEN actual=expected THEN 'PASS' ELSE level END AS result FROM checks)
SELECT check_name,actual,expected,result FROM results
UNION ALL SELECT '99_summary',count(*) FILTER(WHERE result='PASS'),count(*),CASE WHEN count(*) FILTER(WHERE result='FAIL')>0 THEN 'FAIL' WHEN count(*) FILTER(WHERE result IN ('WARN','SKIP'))>0 THEN 'REVIEW' ELSE 'PASS' END FROM results
ORDER BY check_name;
ROLLBACK;
